\"\"\"Minimal standard-library-only client for OpenAI's Responses API.

Send a private text prompt from the command line or import the module:

    from openai_client import send_prompt
    print(send_prompt(\"Summarise the second law of thermodynamics.\"))

The API key is read from the "'``OPENAI_API_KEY`` environment variable so it
never has to be hard-coded, and requests are sent with ``store=False`` so
OpenAI does not retain the prompt or response for training or evals.
"""

import json
import os
import urllib.error
import urllib.request

API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4.1-mini")


class OpenAIError(RuntimeError):
    """Raised when the OpenAI API returns an error or is unreachable."""


def _extract_text(payload):
    """Pull the assistant text out of a Responses API payload."""
    chunks = []
    for item in payload.get("output", []) or []:
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        for part in item.get("content", []) or []:
            text = part.get("text") if isinstance(part, dict) else None
            if text:
                chunks.append(text)
    if chunks:
        return "".join(chunks)
    return payload.get("output_text", "")


def send_prompt(prompt, *, model=DEFAULT_MODEL, instructions=None,
                store=False, extra_body=None, timeout=60):
    """Send a private text prompt and return the model'"'s reply as a string.

    "'``store`` defaults to ``False`` so the request is not retained by OpenAI.
    ``extra_body`` is merged into the request body for advanced parameters
    (for example ``temperature`` or ``max_output_tokens``).
    """
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")

    api_key = [REDACTED_SECRET]"OPENAI_API_KEY")
    if not api_key:
        raise OpenAIError("OPENAI_API_KEY environment variable is not set")

    body = {
        "model": model,
        "input": prompt,
        "store": store,
    }
    if instructions is not None:
        body["instructions"] = instructions
    if extra_body:
        body.update(extra_body)

    request = urllib.request.Request(
        API_URL,
        data=json.dumps(body).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
            "User-Agent": "openai_client.py/1.0 (stdlib)",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read().decode("utf-8")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise OpenAIError("HTTP {}: {}".format(exc.code, detail)) from exc
    except urllib.error.URLError as exc:
        raise OpenAIError("Network error: {}".format(exc.reason)) from exc

    return _extract_text(json.loads(raw))


if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2:
        print("Usage: python openai_client.py <prompt>", file=sys.stderr)
        sys.exit(2)
    print(send_prompt(sys.argv[1]))
